"""Grounded answers with citations, generated by a local LLM from the retrieved chunks.

    python -m leafscan.rag.generate --condition retrieved   # -> reports/rag/answers_retrieved.jsonl
    python -m leafscan.rag.generate --condition oracle

Plan and metrics: research log, 2026-10-29.
"""

from __future__ import annotations

import argparse
import json
import re
import time
from pathlib import Path

from leafscan.rag.corpus import chunk_pages, load_pages
from leafscan.rag.evalset import load_questions, relevant_chunks
from leafscan.rag.retrieval import Dense

LLM = "Qwen/Qwen3-4B-Instruct-2507"
RETRIEVER = "BAAI/bge-small-en-v1.5"
TOP_K = 5
MAX_NEW_TOKENS = 220
ABSTAIN = "I don't know based on the available sources."

SYSTEM = f"""You answer questions from growers about plant diseases.
Use ONLY the numbered sources given with the question, never your own knowledge.
Answer in at most 4 short sentences, in plain English.
After every sentence, put the number of the source(s) that support it, like [2] or [1][3].
If the sources do not contain the answer, reply exactly: {ABSTAIN}"""


def format_context(chunks: list[dict]) -> str:
    return "\n\n".join(f"[{i}] ({c['section']})\n{c['text']}" for i, c in enumerate(chunks, 1))


def build_messages(question: str, chunks: list[dict]) -> list[dict]:
    return [{"role": "system", "content": SYSTEM},
            {"role": "user", "content": f"Sources:\n\n{format_context(chunks)}\n\n"
                                        f"Question: {question}"}]


def oracle_context(question: dict, retrieved: list[dict], all_chunks: list[dict]) -> list[dict]:
    """The retrieved chunks, with the last one replaced by a gold chunk if none is present."""
    gold = set(relevant_chunks(question, all_chunks))
    if not gold or any(c["id"] in gold for c in retrieved):
        return retrieved
    first_gold = next(c for c in all_chunks if c["id"] in gold)
    return retrieved[:-1] + [first_gold]


CITATION = re.compile(r"\[(\d+)\]")


def split_sentences(answer: str) -> list[str]:
    """Sentences of an answer; citations that follow a full stop stay with their sentence."""
    parts = re.split(r"(?<=[.!?])\s+(?=[A-Z])|(?<=\])\s+(?=[A-Z])", answer.strip())
    return [p.strip() for p in parts if p.strip()]


def parse(answer: str, n_sources: int) -> dict:
    """Abstention flag, and each sentence with the source numbers it cites."""
    abstained = "i don't know" in answer.lower() or "i do not know" in answer.lower()
    sentences = []
    for s in split_sentences(answer):
        cited = [int(n) for n in CITATION.findall(s)]
        sentences.append({"text": CITATION.sub("", s).strip(), "cited": cited,
                          "valid": bool(cited) and all(1 <= n <= n_sources for n in cited)})
    return {"abstained": abstained, "sentences": [] if abstained else sentences}


class Generator:
    def __init__(self, model_name: str = LLM, device: str = "mps"):
        import torch
        from transformers import AutoModelForCausalLM, AutoTokenizer

        self.tok = AutoTokenizer.from_pretrained(model_name)
        self.model = AutoModelForCausalLM.from_pretrained(model_name, dtype=torch.bfloat16)
        self.model.to(device).eval()
        self.device = device

    def __call__(self, messages: list[dict]) -> str:
        import torch

        x = self.tok.apply_chat_template(messages, add_generation_prompt=True,
                                         return_tensors="pt", return_dict=True).to(self.device)
        with torch.no_grad():
            out = self.model.generate(**x, max_new_tokens=MAX_NEW_TOKENS, do_sample=False)
        return self.tok.decode(out[0, x["input_ids"].shape[1]:], skip_special_tokens=True).strip()


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--condition", choices=["retrieved", "oracle"], required=True)
    ap.add_argument("--split", choices=["dev", "test", "all"], default="all")
    args = ap.parse_args()

    chunks = chunk_pages(load_pages(), 200)
    by_id = {c["id"]: c for c in chunks}
    retriever, generate = Dense(chunks, RETRIEVER), Generator()
    questions = [q for q in load_questions() if args.split in ("all", q["split"])]
    out = Path(f"reports/rag/answers_{args.condition}.jsonl")
    done = {json.loads(line)["id"] for line in out.read_text().splitlines()} \
        if out.exists() else set()            # resumable: long runs on a laptop
    with out.open("a") as f:
        for q in questions:
            if q["id"] in done:
                continue
            context = [by_id[cid] for cid, _ in retriever.search(q["question"], TOP_K)]
            if args.condition == "oracle":
                context = oracle_context(q, context, chunks)
            t0 = time.time()
            answer = generate(build_messages(q["question"], context))
            row = {"id": q["id"], "type": q["type"], "split": q["split"],
                   "context": [c["id"] for c in context], "answer": answer,
                   "seconds": round(time.time() - t0, 1), "model": LLM}
            f.write(json.dumps(row, ensure_ascii=False) + "\n")
            f.flush()
            print(q["id"], row["seconds"], "s |", answer[:100].replace("\n", " "), flush=True)


if __name__ == "__main__":
    main()
